import { useState, useEffect } from 'react';
import { Sun, Menu, X, Calendar, Book, MapPin, Phone, Mail, Camera, Clock } from 'lucide-react';

export default function HomePage() {
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [currentLanguage, setCurrentLanguage] = useState('english');
  const [scrolled, setScrolled] = useState(false);
  
  // Language content
  const content = {
    english: {
      navLinks: ['Home', 'Gallery', 'Events', 'Services', 'Construction', 'Contact'],
      heroTitle: 'Sri Ayyappan Temple',
      heroSubtitle: 'A Sacred Place of Worship and Community',
      welcome: 'Welcome to our Temple',
      welcomeText: 'Our temple is dedicated to Lord Ayyappan, serving as a spiritual center for devotees. We provide a peaceful environment for worship and various religious services.',
      upcomingEvents: 'Upcoming Events',
      dailyActivities: 'Daily Activities',
      activities: [
        { time: '5:00 AM', name: 'Morning Prayers' },
        { time: '8:00 AM', name: 'Abhishekam' },
        { time: '12:00 PM', name: 'Noon Aarti' },
        { time: '6:00 PM', name: 'Evening Prayers' }
      ],
      events: [
        { date: 'May 1, 2025', name: 'Ayyappa Jayanti' },
        { date: 'June 15, 2025', name: 'Temple Anniversary' }
      ],
      construction: 'Mandapam Construction',
      constructionText: 'We are currently expanding our temple with a new Mandapam. Your support and contributions are welcome.',
      visitUs: 'Visit Us'
    },
    tamil: {
      navLinks: ['முகப்பு', 'புகைப்பட தொகுப்பு', 'நிகழ்வுகள்', 'சேவைகள்', 'கட்டுமானம்', 'தொடர்பு'],
      heroTitle: 'ஸ்ரீ ஐயப்பன் கோவில்',
      heroSubtitle: 'வழிபாடு மற்றும் சமூகத்தின் புனித இடம்',
      welcome: 'எங்கள் கோவிலுக்கு வரவேற்கிறோம்',
      welcomeText: 'எங்கள் கோவில் கடவுள் ஐயப்பனுக்கு அர்ப்பணிக்கப்பட்டது, பக்தர்களுக்கு ஆன்மீக மையமாக பணியாற்றுகிறது. வழிபாடு மற்றும் பல்வேறு மத சேவைகளுக்கு அமைதியான சூழலை நாங்கள் வழங்குகிறோம்.',
      upcomingEvents: 'வரவிருக்கும் நிகழ்வுகள்',
      dailyActivities: 'தினசரி செயல்பாடுகள்',
      activities: [
        { time: '5:00 AM', name: 'காலை பிரார்த்தனைகள்' },
        { time: '8:00 AM', name: 'அபிஷேகம்' },
        { time: '12:00 PM', name: 'நண்பகல் ஆரத்தி' },
        { time: '6:00 PM', name: 'மாலை பிரார்த்தனைகள்' }
      ],
      events: [
        { date: 'மே 1, 2025', name: 'ஐயப்ப ஜெயந்தி' },
        { date: 'ஜூன் 15, 2025', name: 'கோவில் ஆண்டு விழா' }
      ],
      construction: 'மண்டபம் கட்டுமானம்',
      constructionText: 'நாங்கள் தற்போது புதிய மண்டபத்துடன் எங்கள் கோவிலை விரிவுபடுத்துகிறோம். உங்கள் ஆதரவு மற்றும் பங்களிப்புகள் வரவேற்கப்படுகின்றன.',
      visitUs: 'எங்களை சந்திக்கவும்'
    }
  };

  // Handle scroll effect for navbar
  useEffect(() => {
    const handleScroll = () => {
      setScrolled(window.scrollY > 50);
    };
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  // Animation on component mount
  useEffect(() => {
    const timer = setTimeout(() => {
      document.getElementById('hero-content').classList.replace('opacity-0', 'opacity-100');
      document.getElementById('hero-content').classList.replace('translate-y-10', 'translate-y-0');
    }, 300);
    return () => clearTimeout(timer);
  }, []);

  const toggleLanguage = () => {
    setCurrentLanguage(currentLanguage === 'english' ? 'tamil' : 'english');
  };

  return (
    <div className="min-h-screen bg-amber-50">
      {/* Navbar */}
      <nav className={`fixed w-full transition-all duration-300 z-30 ${scrolled ? 'bg-orange-800 shadow-lg py-2' : 'bg-transparent py-4'}`}>
        <div className="container mx-auto px-4">
          <div className="flex justify-between items-center">
            <div className="flex items-center space-x-2">
              <Sun className={`${scrolled ? 'text-amber-200' : 'text-orange-500'} h-8 w-8`} />
              <span className={`font-bold text-lg ${scrolled ? 'text-white' : 'text-orange-800'}`}>
                {content[currentLanguage].heroTitle}
              </span>
            </div>
            
            {/* Desktop Navigation */}
            <div className="hidden md:flex space-x-6">
              {content[currentLanguage].navLinks.map((link, index) => (
                <a 
                  key={index} 
                  href={`#${link.toLowerCase()}`} 
                  className={`${scrolled ? 'text-white hover:text-amber-200' : 'text-orange-800 hover:text-orange-600'} transition-colors duration-200`}
                >
                  {link}
                </a>
              ))}
            </div>
            
            <div className="flex items-center space-x-4">
              <button 
                onClick={toggleLanguage}
                className={`px-3 py-1 rounded-md ${scrolled ? 'bg-amber-200 text-orange-800' : 'bg-orange-800 text-white'} hover:opacity-90 transition-opacity`}
              >
                {currentLanguage === 'english' ? 'தமிழ்' : 'English'}
              </button>
              
              {/* Mobile menu button */}
              <button 
                className="md:hidden"
                onClick={() => setIsMenuOpen(!isMenuOpen)}
              >
                {isMenuOpen ? 
                  <X className={scrolled ? 'text-white' : 'text-orange-800'} /> : 
                  <Menu className={scrolled ? 'text-white' : 'text-orange-800'} />
                }
              </button>
            </div>
          </div>
        </div>
        
        {/* Mobile Navigation */}
        {isMenuOpen && (
          <div className="md:hidden bg-orange-800 shadow-lg mt-2 py-4 px-4 absolute w-full">
            <div className="flex flex-col space-y-3">
              {content[currentLanguage].navLinks.map((link, index) => (
                <a 
                  key={index} 
                  href={`#${link.toLowerCase()}`} 
                  className="text-white hover:text-amber-200 transition-colors duration-200"
                  onClick={() => setIsMenuOpen(false)}
                >
                  {link}
                </a>
              ))}
            </div>
          </div>
        )}
      </nav>
      
      {/* Hero Section with Background Image */}
      <div className="relative h-screen">
        <div className="absolute inset-0 bg-black opacity-50 z-10"></div>
        <div 
          className="absolute inset-0 bg-cover bg-center z-0" 
          style={{ backgroundImage: "url('/api/placeholder/1920/1080')" }}
        ></div>
        
        <div id="hero-content" className="relative z-20 flex flex-col items-center justify-center h-full text-white transition-all duration-700 ease-out opacity-0 translate-y-10">
          <h1 className="text-4xl md:text-6xl font-bold text-center mb-4 text-amber-200">
            {content[currentLanguage].heroTitle}
          </h1>
          <p className="text-xl md:text-2xl text-center max-w-2xl px-4">
            {content[currentLanguage].heroSubtitle}
          </p>
          <div className="mt-8 flex space-x-4">
            <a href="#events" className="bg-orange-600 hover:bg-orange-700 text-white px-6 py-3 rounded-lg font-medium transition-colors duration-200">
              {content[currentLanguage].upcomingEvents}
            </a>
            <a href="#contact" className="bg-transparent border-2 border-white hover:bg-white hover:text-orange-800 text-white px-6 py-3 rounded-lg font-medium transition-colors duration-200">
              {content[currentLanguage].visitUs}
            </a>
          </div>
        </div>
      </div>
      
      {/* Welcome Section */}
      <section className="py-16 px-4 bg-white">
        <div className="container mx-auto">
          <div className="max-w-4xl mx-auto text-center">
            <h2 className="text-3xl md:text-4xl font-bold text-orange-800 mb-6">
              {content[currentLanguage].welcome}
            </h2>
            <p className="text-lg text-gray-700 leading-relaxed">
              {content[currentLanguage].welcomeText}
            </p>
          </div>
        </div>
      </section>
      
      {/* Activities and Events Section */}
      <section id="events" className="py-16 px-4 bg-amber-50">
        <div className="container mx-auto">
          <div className="grid md:grid-cols-2 gap-12">
            {/* Daily Activities */}
            <div className="bg-white rounded-xl shadow-lg p-6 md:p-8 hover:shadow-xl transition-shadow duration-300">
              <div className="flex items-center mb-6">
                <Clock className="text-orange-600 h-8 w-8 mr-3" />
                <h3 className="text-2xl font-bold text-orange-800">
                  {content[currentLanguage].dailyActivities}
                </h3>
              </div>
              <ul className="space-y-4">
                {content[currentLanguage].activities.map((activity, index) => (
                  <li key={index} className="flex items-center">
                    <span className="bg-orange-100 text-orange-800 rounded-lg px-3 py-1 text-sm font-medium mr-3">
                      {activity.time}
                    </span>
                    <span className="text-gray-700">{activity.name}</span>
                  </li>
                ))}
              </ul>
            </div>
            
            {/* Upcoming Events */}
            <div className="bg-white rounded-xl shadow-lg p-6 md:p-8 hover:shadow-xl transition-shadow duration-300">
              <div className="flex items-center mb-6">
                <Calendar className="text-orange-600 h-8 w-8 mr-3" />
                <h3 className="text-2xl font-bold text-orange-800">
                  {content[currentLanguage].upcomingEvents}
                </h3>
              </div>
              <ul className="space-y-4">
                {content[currentLanguage].events.map((event, index) => (
                  <li key={index} className="flex items-center">
                    <span className="bg-orange-100 text-orange-800 rounded-lg px-3 py-1 text-sm font-medium mr-3">
                      {event.date}
                    </span>
                    <span className="text-gray-700">{event.name}</span>
                  </li>
                ))}
              </ul>
            </div>
          </div>
        </div>
      </section>
      
      {/* Construction Update */}
      <section className="py-16 px-4 bg-white">
        <div className="container mx-auto">
          <div className="max-w-4xl mx-auto text-center">
            <h2 className="text-3xl md:text-4xl font-bold text-orange-800 mb-6">
              {content[currentLanguage].construction}
            </h2>
            <p className="text-lg text-gray-700 leading-relaxed mb-8">
              {content[currentLanguage].constructionText}
            </p>
            <div className="bg-amber-100 p-6 rounded-xl">
              <div className="w-full bg-amber-200 rounded-full h-4">
                <div className="bg-orange-600 h-4 rounded-full w-2/5"></div>
              </div>
              <p className="mt-4 text-orange-800 font-medium">40% Completed</p>
            </div>
          </div>
        </div>
      </section>
      
      {/* Footer */}
      <footer className="bg-orange-800 text-white py-12">
        <div className="container mx-auto px-4">
          <div className="grid md:grid-cols-3 gap-8">
            <div>
              <div className="flex items-center space-x-2 mb-4">
                <Sun className="text-amber-200 h-6 w-6" />
                <span className="font-bold text-lg text-amber-200">
                  {content[currentLanguage].heroTitle}
                </span>
              </div>
              <p className="text-amber-100">
                123 Temple Street<br />
                Chennai, Tamil Nadu 600001<br />
                India
              </p>
            </div>
            <div>
              <h4 className="text-lg font-semibold mb-4 text-amber-200">Contact</h4>
              <div className="space-y-3">
                <div className="flex items-center">
                  <Phone className="text-amber-200 h-4 w-4 mr-2" />
                  <span>+91 98765 43210</span>
                </div>
                <div className="flex items-center">
                  <Mail className="text-amber-200 h-4 w-4 mr-2" />
                  <span>info@ayyappantemple.org</span>
                </div>
                <div className="flex items-center">
                  <MapPin className="text-amber-200 h-4 w-4 mr-2" />
                  <span>Get Directions</span>
                </div>
              </div>
            </div>
            <div>
              <h4 className="text-lg font-semibold mb-4 text-amber-200">Quick Links</h4>
              <ul className="space-y-2">
                {content[currentLanguage].navLinks.map((link, index) => (
                  <li key={index}>
                    <a href={`#${link.toLowerCase()}`} className="hover:text-amber-200 transition-colors">
                      {link}
                    </a>
                  </li>
                ))}
              </ul>
            </div>
          </div>
          <div className="border-t border-orange-700 mt-8 pt-8 text-center text-amber-100">
            <p>&copy; 2025 Sri Ayyappan Temple. All rights reserved.</p>
          </div>
        </div>
      </footer>
    </div>
  );
}